func TestValidateRejects(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name    string
		mutate  func(cfg *clusterSettings)
		wantErr string
	}{
		{"NoHosts", func(c *clusterSettings) { c.Hosts = nil }, ErrNoHosts.Error()},
		{"AuthenticatorAndAuthProvider", func(c *clusterSettings) {
			c.Authenticator = PasswordAuthenticator{}
			c.AuthProvider = func(*HostInfo) (Authenticator, error) { return nil, nil }
		}, "both Authenticator and AuthProvider"},
		{"NilInitialReconnectionPolicy", func(c *clusterSettings) { c.InitialReconnectionPolicy = nil }, "InitialReconnectionPolicy is nil"},
		{"InitialReconnectionPolicyNoRetries", func(c *clusterSettings) {
			c.InitialReconnectionPolicy = &ConstantReconnectionPolicy{MaxRetries: 0}
		}, "InitialReconnectionPolicy.GetMaxRetries"},
		{"NilReconnectionPolicy", func(c *clusterSettings) { c.ReconnectionPolicy = nil }, "ReconnectionPolicy is nil"},
		// hostConnPool.InternalConnect makes GetMaxRetries attempts; with none every pool
		// fill fails.
		{"ReconnectionPolicyNoRetries", func(c *clusterSettings) {
			c.ReconnectionPolicy = &ConstantReconnectionPolicy{MaxRetries: 0}
		}, "ReconnectionPolicy.GetMaxRetries"},
		{"NegativePageSize", func(c *clusterSettings) { c.PageSize = -1 }, "PageSize"},
		{"NegativeMaxRoutingKeyInfo", func(c *clusterSettings) { c.MaxRoutingKeyInfo = -1 }, "MaxRoutingKeyInfo"},
		{"NegativeMaxPreparedStmts", func(c *clusterSettings) { c.MaxPreparedStmts = -1 }, "MaxPreparedStmts"},
		{"NegativeSocketKeepalive", func(c *clusterSettings) { c.SocketKeepalive = -time.Second }, "SocketKeepalive"},
		{"NegativeMaxRequestsPerConn", func(c *clusterSettings) { c.MaxRequestsPerConn = -1 }, "MaxRequestsPerConn"},
		{"NegativeNumConns", func(c *clusterSettings) { c.NumConns = -1 }, "NumConns"},
		{"PortTooLarge", func(c *clusterSettings) { c.Port = 65536 }, "valid port number"},
		{"NegativePort", func(c *clusterSettings) { c.Port = -1 }, "valid port number"},
		{"MixedHostPorts", func(c *clusterSettings) { c.Hosts = []string{"10.0.0.1:9042", "10.0.0.2"} }, "all include a port or none"},
		{"NegativeWriteTimeout", func(c *clusterSettings) { c.WriteTimeout = -time.Second }, "WriteTimeout"},
		{"NegativeTimeout", func(c *clusterSettings) { c.Timeout = -time.Second }, "Timeout should be"},
		{"NegativeConnectTimeout", func(c *clusterSettings) { c.ConnectTimeout = -time.Second }, "ConnectTimeout"},
		{"NegativeMetadataSchemaRequestTimeout", func(c *clusterSettings) { c.MetadataSchemaRequestTimeout = -time.Second }, "MetadataSchemaRequestTimeout"},
		{"NegativeWriteCoalesceWaitTime", func(c *clusterSettings) { c.WriteCoalesceWaitTime = -time.Second }, "WriteCoalesceWaitTime"},
		{"NegativeReconnectInterval", func(c *clusterSettings) { c.ReconnectInterval = -time.Second }, "ReconnectInterval"},
		{"NegativeMaxWaitSchemaAgreement", func(c *clusterSettings) { c.MaxWaitSchemaAgreement = -time.Second }, "MaxWaitSchemaAgreement"},
		{"NonSerialSerialConsistency", func(c *clusterSettings) { c.SerialConsistency = Quorum }, "SERIAL or LOCAL_SERIAL"},
		{"NilDNSResolver", func(c *clusterSettings) { c.DNSResolver = nil }, "DNSResolver is empty"},
		{"NegativeMaxExcessShardConnectionsRate", func(c *clusterSettings) { c.MaxExcessShardConnectionsRate = -1 }, "MaxExcessShardConnectionsRate"},
		{"ClientRoutesWithAddressTranslator", func(c *clusterSettings) {
			c.ClientRoutesConfig = &ClientRoutesConfig{}
			c.AddressTranslator = AddressTranslatorFunc(func(addr net.IP, port int) (net.IP, int) { return addr, port })
		}, "should not be set at the same time"},
		{"InvalidClientRoutesConfig", func(c *clusterSettings) { c.ClientRoutesConfig = &ClientRoutesConfig{} }, "ClientRoutesConfig is invalid"},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			cfg := newClusterSettings("10.0.0.1")
			cfg.Logger = nopLogger{}
			if err := cfg.Validate(); err != nil {
				t.Fatalf("baseline config invalid: %v", err)
			}

			cfg = newClusterSettings("10.0.0.1")
			cfg.Logger = nopLogger{}
			tc.mutate(cfg)
			err := cfg.Validate()
			if err == nil || !strings.Contains(err.Error(), tc.wantErr) {
				t.Fatalf("Validate() = %v, want an error containing %q", err, tc.wantErr)
			}
		})
	}
}

