	empty := func() *HostInfo {
		opaqueStorageValuex := new(HostInfo)
		return opaqueStorageValuex
	}()

	implEndpoint.InternalHostInfoUpdate(empty, from)
	if empty.DataCenter() != "dc-new" || empty.Rack() != "r-new" || empty.HostID() != from.HostID() ||
