func TestRingDiscovery(t *testing.T) {
	t.Parallel()

	clusterHosts := getClusterHosts()
	cluster := createV2Cluster()
	cluster.ContactPoints = clusterHosts[:1]

	session := createV2SessionFromConfig(cluster, t, false)
