	strict := StreamRow(func(r *record) {}, StreamColumn("id", StreamInt32, func(r *record) *int32 { return &r.ID }))
	if _, err := StreamUDT(UDTOptions{Keyspace: "ks", Name: "entry"}, strict).Compile(udt); err == nil {
