	}
	wrapped := cqltype.EmptyValueOf[Unit]{}
	if err := StreamDecodeFixture(t, zero, StreamEmpty(StreamTuple(StreamRow(func(*Unit) {}))), empty, &wrapped, 1); err != nil || !wrapped.Empty {
