func (r *StreamValueReader) count(minimum int64) (int, error) {
	v, err := r.Uint32()
	if err != nil {
		return 0, err
	}
	n := int64(int32(v))
	if n < 0 {
		return 0, r.fail(wire.ErrLength)
	}
	if n > r.scope.Limits().MaxCount || (minimum > 0 && n > r.Remaining()/minimum) {
		return 0, r.fail(wire.ErrLimit)
	}
	return int(n), nil
}

