func checkUDTIdentity(typ cqltype.DataType, options UDTOptions) error {
	ks, name, ok := typ.UDTName()
	if !ok || options.Keyspace == "" || options.Name == "" {
		return cqltype.TypeValidation("UDT identity", "expected keyspace and name are required")
	}
	if ks != options.Keyspace || name != options.Name {
		return cqltype.TypeValidation("UDT identity", "expected %s.%s, got %s.%s", options.Keyspace, options.Name, ks, name)
	}
	return nil
}

