func compileUDTRows[T any](codec rowCodec[T], columns cqltype.Columns, options UDTOptions) (RowPlan[T], error) {
	locations := make([]fieldLocation, len(codec.fields))
	for i, field := range codec.fields {
		if field == nil {
			return nil, cqltype.TypeValidation("field", "nil UDT output field")
		}
		locations[i] = field.location()
	}
	mapping, err := udtFieldMapping(columns, locations, options)
	if err != nil {
		return nil, err
	}
	plan := rowPlan[T]{ordered: make([]OutputField[T], len(mapping)), scratch: &sync.Pool{New: func() any { return new(T) }}}
	for index, field := range mapping {
		if field == -1 {
			plan.ordered[index] = ignoredField[T]{}
			continue
		}
		compiled, err := codec.fields[field].compile(cqltype.ColumnSlice(columns)[index].Type)
		if err != nil {
			return nil, fmt.Errorf("gocql: UDT field %q: %w", cqltype.ColumnSlice(columns)[index].Name, err)
		}
		plan.ordered[index] = compiled
	}
	return plan, nil
}

