func NewSniHostDialer(connConfig *ConnectionConfig, dialer gocql.Dialer) *SniHostDialer {
	if dialer == nil {
		dialer = gocql.DefaultDialer{}
	}
	return &SniHostDialer{connConfig: connConfig, dialer: dialer}
}

