							if ok, err := decodeStreamRow(response, plan, &dst); !ok || err != nil {
								t.Fatal(ok, err)
							}
							sample()
						}
						if ok, err := decodeStreamRow(response, plan, &dst); ok || err != nil {
							t.Fatal(ok, err)
						}
					} else {
						plan := codecTestMust(StreamOneColumn(StreamBlob).Compile(response.InternalColumns))
