			serverDone := make(chan error, 1)
			go func() {
				_, stream, _, err := step03ReadRequest(peers[0])
				close(received)
				<-release
				if err == nil {
					_, err = peers[0].Write(typedTestResponse(t, 4, stream, step03PreparedBody([]byte("late"), NewColumns(), cols)))
				}
				serverDone <- err
			}()
			result := make(chan *hostPrepared, 1)
