				}
			} else if err != nil || recorder.borrowed != len(payload) {
				t.Fatal("ordered TLS spans", err, recorder.borrowed)
			}
			if !released.Load() {
				t.Fatal("accepted TLS writer input did not drain")
			}
			if err := <-serverDone; err != nil {
				t.Fatal("TLS peer", err)
			}
		})
	}
}

